package com.alan.clients.module.impl.exploit.disabler;

import com.alan.clients.event.Listener;
import com.alan.clients.event.annotations.EventLink;
import com.alan.clients.event.impl.packet.PacketSendEvent;
import com.alan.clients.module.impl.exploit.Disabler;
import com.alan.clients.value.Mode;
import net.minecraft.network.Packet;
import net.minecraft.network.play.client.C02PacketUseEntity;
import net.minecraft.network.play.client.C03PacketPlayer;
import net.minecraft.network.play.client.C0FPacketConfirmTransaction;
import net.minecraft.network.play.server.S07PacketRespawn;

public class UniversoCraftDisabler extends Mode<Disabler> {
    private boolean disabling;

    public UniversoCraftDisabler(String name, Disabler parent) {
        super(name, parent);
    }

    @EventLink
    public final Listener<PacketSendEvent> onPacketSend = event -> {
        Packet<?> packet = event.getPacket();

        if (packet instanceof S07PacketRespawn) {
            disabling = true;
        } else if (packet instanceof C02PacketUseEntity) {
            disabling = false;
        } else if (packet instanceof C03PacketPlayer && mc.thePlayer.ticksExisted <= 10) {
            disabling = true;
        } else if (packet instanceof C0FPacketConfirmTransaction && disabling && mc.thePlayer.ticksExisted < 350) {
            ((C0FPacketConfirmTransaction) event.getPacket()).setUid(
                    mc.thePlayer.ticksExisted % 2 == 0 ? Short.MIN_VALUE : Short.MAX_VALUE);
        }
    };
}

// NOTE (AI): S07PacketRespawn is tested inside a PacketSendEvent listener even though it
// is a clientbound packet; in Rise's event pipeline this branch only matters if clientbound
// traffic reaches the send listener, otherwise the flag is armed exclusively by the C03
// branch (first 10 ticks). The corruption window (ticksExisted < 350, alternating
// Short.MIN_VALUE / Short.MAX_VALUE uids) targets transaction-continuity checks on
// UniversoCraft, and the disabling flag is cleared by any C02 attack.
